/**
 * @summary Used to remove the top border when a table's header is visually hidden
 *
 * @name hidden-header
 * @selector .slds-table_header-hidden
 * @restrict .slds-table
 * @support dev-ready
 * @variant
 * @lwc
 */
.slds-table_header-hidden {
  border-top: 0;
}

// Lightning Design System 2.264.1
